package dev.pshell.app.zepp

import org.junit.Assert.assertEquals
import org.junit.Test

/** The phone's parsing of fetched data against scripts/amazfit/zepp/fetch.py's for the same bytes. */
class FetchTest {
	private fun hex(s: String) = s.chunked(2).map { it.toInt(16).toByte() }.toByteArray()

	@Test
	fun activityMatchesThePc() {
		val out = Fetcher.parse("activity", 1793700000, hex("010a144600000000730000ff00000000780500370001323c"))
		assertEquals(3, out.size)
		assertEquals(1793700120L, out[2].getLong("t"))
		assertEquals(120, out[2].getInt("k")); assertEquals(55, out[2].getInt("h")); assertEquals(50, out[2].getInt("d")); assertEquals(60, out[2].getInt("r"))
		assertEquals(20, out[0].getInt("s")); assertEquals(255, out[1].getInt("h"))
	}

	@Test
	fun sleepMatchesThePc() {
		val s = Fetcher.parse("sleep", 0, hex(""))[0]
		assertEquals(1793610000L, s.getLong("bed")); assertEquals(1793638860L, s.getLong("wake"))
		assertEquals(81, s.getInt("score")); assertEquals(58, s.getInt("avgHr"))
		assertEquals(120, s.getInt("deep")); assertEquals(250, s.getInt("light")); assertEquals(30, s.getInt("rem")); assertEquals(20, s.getInt("awake"))
		val st = s.getJSONArray("stages")
		assertEquals("deep", st.getJSONArray(1).getString(0)); assertEquals(1793616060L, st.getJSONArray(1).getLong(1)); assertEquals(1793638860L, st.getJSONArray(1).getLong(2))
	}

	@Test
	fun timeRoundTrip() {
		val t = 1793700000L
		assertEquals(t, Fetcher.parseTime(Fetcher.timeBytes(t), 0))
	}
}
